from __future__ import annotations

import decimal
from decimal import Decimal, DivisionByZero, InvalidOperation, Overflow
from typing import Iterable

CTX = decimal.Context(
    prec=10_000,
    Emax=decimal.MAX_EMAX,
    Emin=decimal.MIN_EMIN,
    traps=[InvalidOperation, Overflow, DivisionByZero],
)

_CENT = Decimal("0.01")


def fmt_money(v: Decimal) -> str:
    q = v.quantize(_CENT, rounding=decimal.ROUND_HALF_UP, context=CTX)
    if q == 0:
        return "0.00"
    return format(q, "f")


def parse_decimal(s: str) -> Decimal:
    return Decimal(s)


def dsum(values: Iterable[Decimal]) -> Decimal:
    total = Decimal(0)
    for v in values:
        total = CTX.add(total, v)
    return total

from __future__ import annotations

import csv
import io

from .errors import LedgerError


def open_table(path, required, code):
    try:
        with open(path, "rb") as f:
            data = f.read()
    except OSError:
        raise LedgerError(code, f"{path}: cannot read file") from None
    try:
        text = data.decode("utf-8-sig")
    except UnicodeDecodeError:
        raise LedgerError(code, f"{path}: not valid UTF-8") from None

    reader = csv.reader(io.StringIO(text, newline=""))
    try:
        header = next(reader, None)
    except csv.Error:
        raise LedgerError(code, f"{path}:{reader.line_num}: malformed CSV") from None
    if header is None:
        raise LedgerError(code, f"{path}: missing header")

    names = [h.strip().lower() for h in header]
    seen = set()
    for n in names:
        if n in seen:
            raise LedgerError(code, f"{path}: duplicate column '{n}'")
        seen.add(n)
    for r in required:
        if r not in seen:
            raise LedgerError(code, f"{path}: missing column '{r}'")

    width = len(header)

    def rows():
        while True:
            try:
                rec = next(reader, None)
            except csv.Error:
                raise LedgerError(
                    code, f"{path}:{reader.line_num}: malformed CSV"
                ) from None
            if rec is None:
                return
            if rec == []:
                continue
            line = reader.line_num
            if len(rec) != width:
                raise LedgerError(
                    code, f"{path}:{line}: expected {width} fields, got {len(rec)}"
                )
            yield line, rec

    return names, rows()

