from __future__ import annotations

import re
from dataclasses import dataclass

from .csvio import open_table
from .errors import EXIT_RULES, LedgerError
from .transactions import Categorized, Transaction

_PRIORITY = re.compile(r"-?[0-9]+")


@dataclass(frozen=True)
class Rule:
    category: str
    type: str
    pattern: str
    priority: int
    index: int
    compiled: re.Pattern | None


def parse_rules(path) -> list[Rule]:
    names, rows = open_table(
        path, ["category", "type", "pattern", "priority"], EXIT_RULES
    )
    ci, ti, pi, qi = (names.index(n) for n in ("category", "type", "pattern", "priority"))
    out = []
    for line, rec in rows:
        def fail(msg):
            return LedgerError(EXIT_RULES, f"{path}:{line}: {msg}")

        category = rec[ci].strip()
        if not category:
            raise fail("empty category")
        typ = rec[ti].strip()
        if typ not in ("contains", "regex"):
            raise fail(f"invalid type '{typ}'")
        pattern = rec[pi].strip()
        if not pattern:
            raise fail("empty pattern")
        ps = rec[qi].strip()
        try:
            if not _PRIORITY.fullmatch(ps):
                raise ValueError
            priority = int(ps)
        except ValueError:
            raise fail(f"invalid priority '{ps}'") from None
        compiled = None
        if typ == "regex":
            try:
                compiled = re.compile(pattern, re.IGNORECASE)
            except (re.error, RecursionError, OverflowError):
                raise fail(f"invalid regex '{pattern}'") from None
        out.append(Rule(category, typ, pattern, priority, len(out), compiled))
    return out


def assign_category(description: str, rules: list[Rule]) -> str:
    folded = description.casefold()
    best = None
    for r in rules:
        if r.type == "contains":
            hit = r.pattern.casefold() in folded
        else:
            hit = r.compiled.search(description) is not None
        if hit and (best is None or (-r.priority, r.index) < (-best.priority, best.index)):
            best = r
    return best.category if best else "Uncategorized"


def categorize_all(txs: list[Transaction], rules: list[Rule]) -> list[Categorized]:
    return [Categorized(t, assign_category(t.description, rules)) for t in txs]

