def dedupe(txs: list[Transaction]) -> tuple[list[Transaction], int]:
    seen = set()
    kept = []
    for t in txs:
        key = (t.date, t.description, t.amount)
        if key in seen:
            continue
        seen.add(key)
        kept.append(t)
    return kept, len(txs) - len(kept)

