@dataclass
class CategoryRow:
    category: str
    count: int
    income: Decimal
    expenses: Decimal
    net: Decimal


@dataclass
class MonthRow:
    month: str
    count: int
    income: Decimal
    expenses: Decimal
    net: Decimal
    categories: list[CategoryRow] = field(default_factory=list)


def filter_month(txs: list[Transaction], month: str | None) -> list[Transaction]:
    if month is None:
        return txs
    return [t for t in txs if t.date[:7] == month]


def sort_by_date(items: list[Categorized]) -> list[Categorized]:
    return sorted(items, key=lambda c: c.tx.date)


def _totals(amounts: list[Decimal]) -> tuple[Decimal, Decimal, Decimal]:
    income = dsum(a for a in amounts if a > 0)
    expenses = dsum(a for a in amounts if a < 0)
    return income, expenses, CTX.add(income, expenses)


def build_report(items: list[Categorized]) -> list[MonthRow]:
    months: dict[str, list[Categorized]] = {}
    for c in items:
        months.setdefault(c.tx.date[:7], []).append(c)
    rows = []
    for month in sorted(months):
        group = months[month]
        inc, exp, net = _totals([c.tx.amount for c in group])
        cats: dict[str, list[Decimal]] = {}
        for c in group:
            cats.setdefault(c.category, []).append(c.tx.amount)
        crows = []
        for name in sorted(cats):
            ci, ce, cn = _totals(cats[name])
            crows.append(CategoryRow(name, len(cats[name]), ci, ce, cn))
        rows.append(MonthRow(month, len(group), inc, exp, net, crows))
    return rows

